    // throws exception when failed to convert
    //
    static byte charToHex(char ctx) throws SQLServerException {
        byte ret = 0;
        if (ctx >= 'A' && ctx <= 'F') {
            ret = (byte) (ctx - 'A' + 10);
        } else if (ctx >= 'a' && ctx <= 'f') {
            ret = (byte) (ctx - 'a' + 10);
        } else if (ctx >= '0' && ctx <= '9') {
            ret = (byte) (ctx - '0');
        } else {
            SQLServerException.makeFromDriverError(null, null, SQLServerException.getErrString("R_stringNotInHex"),
                    null, false);
        }
        return ret;
